fn best_jungle_goal(version, rnd, player, data, team_plan, now_camp: Option<JungleType>, debug) -> JungleType

// --- L807: 후보 캠프 고정 배열 (IR의 store 순서 그대로)
jungle_camps = [Rhino(0), Mushroom(1), Bee(3), Stump(2)]   // Morgard(4)/Serpen(5) 제외
team = player.info.team                                     // PlayerState +0x930

// --- L814~815: 아직 안 정리된 캠프만 bump arena Vec 으로 수집
not_cleared_camps: BumpVec<JungleType> =
    jungle_camps.into_iter()
        .filter(|c| !is_cleared(*c, team, version, rnd, player, data, team_plan, 0, debug))
        .map(|c| c)
        .collect_in(data.context.pool)          // GameContext +0x00 = &bumpalo::Bump
// 필터 술어의 실체 = m04.ll:66311 의 closure$0 call_mut → passive_jungle::is_cleared 의 부정.
// 그 클로저가 캡처하는 것 6개 = [player, &version, rnd, data, team_plan, debug] (env +0x00..0x28),
// 뒤이어 env +0x30/0x38/0x40 에 array IntoIter 상태(alive=0..4, [4 x i8] 데이터)가 붙는다.
// is_cleared 는 version/rnd/debug 를 안 써서 LLVM 이 poison 으로 접었다 — 실제로 쓰는 인자는
// jungle_type, team, player, data, team_plan 그리고 리터럴 0 뿐이다.

// --- L817: 후보가 하나도 없다 = 4캠프 전부 정리된 상태
if not_cleared_camps.len() == 0 {                // BumpVec +0x18
    // L818~819: '가장 먼저 리스폰될 캠프' 로 미리 간다
    runner = data.cache.game.as_moba().unwrap().jungle_runner()
        //   data.cache (OperationData +0x00) = &AbstractGameWithCache
        //   .game       (AGWC +0x00)          = &dyn AbstractGame 팻포인터 (data, vtable)
        //   vtable +0x40 간접호출 = as_moba, 반환 {i64,ptr}; tag != 0 이면 unwrap_failed 패닉
        //   MobaMode +0x18                    = &JungleRunner(480B)
    return jungle_camps.into_iter()
        .min_by_key(|c| runner.get_camp_state(team, *c).next_respawn_tick)  // JungleCampState +0x18
        .unwrap();      // 결과 i8 == -1 이면 unwrap_failed (배열 길이 4라 실제 도달 불가)
}

// --- L823: 자기 챔피언 엔티티 찾기
if team >= 2 { panic_bounds_check(team, 2) }
champion: Option<&Entity> =
    data.cache.player_champion[team][player.info.position.as_index()]
    // AGWC +0x1e0, 레이아웃 [[*const Entity; 5]; 2] → 주소 = base + 480 + team*40 + pos*8

// --- L824~829: 챔피언이 없다(null = 사망/미스폰 등)
if champion.is_none() {
    if now_camp == None {                        // i8 == -1
        return *jungle_camps.choose(rnd).unwrap();   // L829, rand::seq::SliceRandom, 4개 균등
    }
    return now_camp.unwrap();                    // 기존 목표 유지 (RNG 소비 없음)
}

// --- L832~835: 미정리 캠프 중 '내 챔피언에서 가장 가까운' 캠프
blue_side = (team == 0)
return not_cleared_camps.into_iter()
    .min_by_key(|c| {
        (cx, cy) = data.context.map.camp_pos(*c, blue_side);   // GameContext +0x20 = &MapDef
        dx = u64::abs_diff(cx, champion.x);      // Entity +0x660
        dy = u64::abs_diff(cy, champion.y);      // Entity +0x668
        dx*dx + dy*dy                            // 제곱거리 비교, sqrt 없음
    })
    .unwrap();                                   // 결과 i8 == -1 이면 unwrap_failed
// L838 end

// ===== 분기 순서 요약 (IR 블록 라벨 기준) =====
//  %7  : 배열 구성 → filter/map/collect_in → %31 = (len == 0) ?
//        예   → %32  (src 818/819) 리스폰 최소 min_by_key → %69 → ret
//        아니오 → %62 (src 823) team<2 bounds check → %78 champion 조회
//                → null 이면  %88 (src 824) now_camp == None ?
//                              예   → %135 choose(rnd) → %143 → %137
//                              아니오 → %137 (now_camp 그대로)
//                → null 아니면 %90 (src 833) 거리 최소 min_by_key → %127 → ret
//  %66/%103/%73/%139/%146/%147 = 언와인딩 정리 경로(Vec/RawVec/IntoIter Drop, drop_glue)

// ===== 호출 형태 메모 =====
// 본문 호출의 대부분은 `call` 이 아니라 `invoke`(언와인드 엣지 있음) 로 나온다.
// as_moba 는 심볼 없는 **간접 호출**(vtable+0x40 로드 후 %44(...))이라 calls 에 못 적었다.
// is_cleared 는 이 함수 본문이 아니라 필터 클로저 define(m04.ll:66311)에서 호출되므로
// 이 줄범위 텍스트에는 나타나지 않는다 — 빠뜨린 게 아니라 위치가 다른 것이다.
// 두 min_by_key 의 fold 본체는 별도 제네릭 인스턴스(m12.ll:22555 등)에 있다.
